def validateBinaryTreeNodes(n, leftChild, rightChild):
    # Helper function to find the root of the tree
    def find_root():
        children = set(leftChild + rightChild)
        for i in range(n):
            if i not in children:
                return i
        return -1

    # Helper function to perform DFS and check for cycles and multiple roots
    def dfs(node, visited):
        if node == -1:
            return True
        if node in visited:
            return False
        visited.add(node)
        return dfs(leftChild[node], visited) and dfs(rightChild[node], visited)

    root = find_root()
    if root == -1:
        return False

    visited = set()
    if not dfs(root, visited) or len(visited) != n:
        return False

    return True

